const definitions: Record<string, Omit<IndicatorExplanation, "why">[]> = {
  populationSize: [
    item("Population size", "The total number of people living in Ghana in each year shown. Figures are expressed in millions, so 1.0 represents one million people. Census observations come from a population count; intercensal estimates describe the years between censuses, and projections describe the years after the latest census. The different series markings distinguish these sources. Annual estimates and projections should not be read as fresh census counts.", "Ghana’s population rose from 18.9 million in 2000 to 24.7 million in 2010 and 30.8 million in 2021, reaching a projected 33.7 million in 2025. The country added almost 15 million people over 25 years, with no year of decline in the displayed series. The report describes annual additions of roughly half a million to 700,000 people. A rising total and a slowing percentage growth rate can occur at the same time.", "Figure 3.1, p. 12"),
  ],
  populationComposition: [
    item("Intercensal growth rate", "The average annual percentage change in population between two censuses. Each row refers to a whole intercensal period, rather than a single year. Doubling time is the number of years the population would take to double if that period’s growth rate remained unchanged. The growth rate is a percentage; doubling time is measured in years.", "The annual growth rate eased from 2.7% in 1984–2000 to 2.5% in 2000–2010 and 2.1% in 2010–2021. Over the same periods, the reported doubling time lengthened from 25.9 to 28.0 and then 33.3 years. Ghana continued to grow, but each year added a smaller share of people than before. Doubling time illustrates that change; it is not a dated population forecast.", "Table 3.1, p. 13"),
    item("Population doubling time", "How long it would take the population to double if the observed annual growth rate remained unchanged. This is a conditional illustration, not a dated population forecast.", "The reported doubling time lengthened from 25.9 years to 33.3 years, giving more time to prepare services for a larger population.", "Table 3.1, p. 13"),
    item("Male–female composition", "The shares of the population that are male and female. The two shares describe the same population and add to 100%.", "In the 2025 projection, females make up 50.7% and males 49.3%: a near-balanced population with a small female majority.", "pp. 14–15"),
    item("Age–sex structure", "The population pyramid compares males and females within five-year age groups for the selected year. Each horizontal bar shows the number of people in that sex and age group, expressed in millions. Read the ages from the younger groups at the bottom to the older groups at the top, and compare bar lengths across the two sides. The mirrored sides show positive population counts, not negative numbers.", "Use the year selector to compare the 2010 and 2021 census structures with the 2025 projection. The report describes a youthful population, concentrated in adolescent and working ages, with relatively few people in the oldest groups. Changes in the shape show how the sizes of generations differ; they do not by themselves explain why those differences occurred.", "Figure 3.2, p. 14"),
    item("Population by age group", "The percentage of Ghana’s projected 2025 population in each displayed age band. A larger segment means that age group accounts for more of the total population. The groups cover different numbers of ages, so their shares should not be read as counts for a single year of age. They also differ from the 15–24 and 15–35 definitions used in the youth indicators.", "Young adults aged 20–34 form the largest displayed group at 25.6%, followed by ages 35–59 at 23.2% and adolescents aged 10–19 at 20.7%. Children aged 0–4 and 5–9 account for 12.8% and 11.3%, respectively, while people aged 60 and over account for 6.3%. Together, the groups show a population concentrated in younger and working ages. Rounded shares can total slightly less than 100%.", "Figure 3.3, p. 15"),
  ],
  populationLiving: [
    item("Urban and rural population", "The percentage of Ghana’s population living in urban and rural localities in each year. The two shares describe the same national population and together make up 100%. They measure where people live, rather than the amount of land occupied by towns or population density. The final year is a projection, while the earlier census years are observed counts.", "In 2000, most people still lived in rural areas. By 2010 the balance had shifted: urban residents numbered 12.55 million, slightly more than the 12.11 million rural residents. The urban population then continued to grow faster. By 2025, urban areas are projected to hold 58.7% of the population, close to six in every ten people. The falling rural share does not mean the rural population has necessarily fallen in number.", "pp. 16–18"),
    item("Life expectancy at birth", "The average number of years a newborn would be expected to live if the age-specific mortality rates measured at that time continued throughout life. The line therefore summarises survival conditions for the population in each reported year. It is neither a prediction of one person’s lifespan nor an upper age limit. Life expectancy at an older age instead describes additional years after reaching that age.", "Life expectancy at birth increased from 40.3 years in 1960 to 65.1 years in 2021, a gain of 24.8 years. The report identifies the fastest improvement between 1960 and 1980, when the measure rose by 15.7 years. In 2021, female life expectancy was 66.8 years and male life expectancy 63.3 years. The national line summarises this progress while the sex-specific figures show differences hidden by the average.", "Figure 3.9, p. 21"),
    item("Life expectancy at a given age", "The additional years expected for someone who has already reached that age, under the mortality conditions measured.", "Women have higher life expectancy at birth: 66.8 years against 63.3 for men in 2021. At age 60, the remaining years are about 16.0 for women and 15.7 for men.", "Figure 3.10, p. 22"),
    item("Total fertility rate", "The total fertility rate is the number of children a woman would have over her reproductive life if the age-specific fertility rates measured in that year continued. It is expressed as children per woman. It is a summary of current fertility conditions, rather than the average number of children already born to the women surveyed.", "The rate fell from 6.4 children per woman in 1988 to 5.2 in 1993, 4.2 in 2014 and 3.9 in 2022. This is a substantial decline over little more than a generation. The pattern helps explain slowing population growth, although a lower fertility rate does not mean the total population immediately stops increasing.", "p. 19; glossary"),
    item("Average household size", "The average number of people in a household: people who live together and share housekeeping. It is expressed as persons per household, so a value of 3.6 is an average across households rather than the size of every household. A household is also distinct from a residential building, which may contain more than one dwelling unit.", "Average household size rose from 4.9 people in 1984 to 5.1 in 2000, then declined to 4.4 in 2010 and 3.6 in 2021, the lowest level in the reported series. The report associates this decline with fewer children, young people moving to towns for work, and more couples and single adults living on their own.", "p. 20"),
  ],
  migration: [
    item("Regional population share", "The percentage of Ghana’s total population living in each region. A region’s share is distinct from population density, which divides people by land area.", "Greater Accra and Ashanti together hold more than a third of the projected 2025 population. The concentration helps explain the scale of demand for services in these regions.", "Table 2.1, p. 5; p. 18"),
    item("Net migration", "The balance between a region’s in-migrants and out-migrants. In this census-based comparison, migration is identified by comparing region of birth with region of enumeration. Bars above zero indicate net gains and bars below zero indicate net losses; their lengths show the size of the balance in people. These are accumulated census-based differences, rather than a count of moves during 2021 alone.", "Six regions recorded net gains in the 2021 census comparison: Greater Accra, Ashanti, Western, Bono East, Western North and Ahafo. Greater Accra recorded the largest gain, about 1.1 million people. Ten regions recorded net losses, led by Volta at about 435,000 and Upper East at about 292,000. The chart shows the balance, so a negative value does not mean nobody moved into that region.", "Figure 3.11, p. 23"),
    item("Internal migration", "Movement within Ghana, measured here by whether a person was enumerated in a different region from their region of birth. Each percentage is the share recorded as internal migrants at that census. It does not count every move a person made, and it should not be interpreted as the share moving during that census year alone.", "The share recorded as internal migrants rose from 30.2% in 2000 to 34.7% in 2010, then declined to 27.0% in 2021. The report also identifies Greater Accra and Ashanti as leading receiving regions. The series itself does not establish the causes of the change.", "Figures 3.12–3.13, p. 24"),
    item("Immigration", "The share of Ghana’s population recorded as immigrants in the census. A population share differs from the number of people arriving in a particular year.", "The share declined from 1.6% in 2010 to 1.0% in 2021, a fall of 0.6 percentage points.", "Figure 3.17, p. 26"),
    item("Emigration", "Ghanaians living outside the country who were recorded through the census reporting method. This is not an exhaustive count of the worldwide diaspora.", "The recorded count rose from 250,624 in 2010 to 293,416 in 2021. Greater Accra and Ashanti accounted for 54.0% of recorded emigrants.", "Figure 3.14, p. 25"),
    item("Reasons for emigration", "The distribution of reported reasons among emigrants aged 15 and older. It describes this group, not the percentage of all Ghanaians leaving for each reason.", "Employment accounts for 73.4% and education or training 14.6%, making work and study the main reported reasons.", "Figure 3.15, p. 25"),
    item("Emigrant destinations", "The shares of census-recorded emigrants living in the listed destination regions. ECOWAS and Other Africa are separate categories.", "Europe accounts for 37.6%, followed by the Americas at 23.7% and ECOWAS at 23.3%. Rounded destination shares may not total exactly 100%.", "Figure 3.16, p. 26"),
  ],
  education: [
    item("Gross enrolment rate (GER)", "All pupils enrolled at a level, regardless of age, divided by the population of official school age for that level. It can exceed 100% because pupils may be younger or older than that age range.", "In 2023/24, the figure’s legend identifies KG at 115.5%, primary at 103.6% and JHS at 95.5%. These are enrolment ratios, not the probability that an individual child attends school.", "Figure 4.1, p. 29"),
    item("Net enrolment rate (NER)", "Only enrolled children of the official age for a school level, divided by all children of that age. It is the stricter measure of age-appropriate participation.", "JHS net enrolment rose from 44.3% in 2021/22 to 58.8% in 2022/23 and 59.3% in 2023/24. The figure reports primary at 83.2% and KG at 78.0% in 2023/24.", "Figure 4.1, p. 29"),
    item("Completion rate", "An administrative ratio comparing pupils completing a level with the population of the official completion age. Different pupil ages can push it above 100%; it is not a cohort survival probability.", "JHS completion rose from 77.5% in 2019/20 to 88.4% in 2023/24, although it fell from 94.1% in the previous year. Primary completion was 102.0% in 2023/24.", "Figure 4.2, p. 30"),
    item("Pupils per trained teacher", "The number of pupils for each trained teacher at a school level. Compare levels separately: these ratios should not be added.", "KG improved from 96 pupils per trained teacher in 2010/11 to 34 in 2020/21. Lower ratios can support more attention per pupil, but do not measure teaching quality on their own.", "Figure 4.3, p. 30"),
  ],
  health: [
    item("Active health insurance coverage", "Active NHIS membership able to access health services during the year, expressed as a share of Ghana’s population. It is distinct from everyone who has ever registered.", "Coverage rose from 30.0% in 2010 to 66.2% in 2025. The 2025 gain was 10.3 percentage points after coverage stayed between 52.0% and 55.9% during 2019–2024.", "Figure 4.4, p. 31"),
    item("Teenage motherhood", "The share of girls aged 15–19 who already have a child. This is not the same measure as all teenage pregnancies.", "In 2022, the share was 17.2% in rural areas and 9.1% in urban areas; nationally it was 12.8%. The rural–urban gap is much larger than the change in the national average since 2008.", "Figure 4.5, p. 32"),
  ],
  living: [
    item("Housing deficit", "The estimated difference between dwelling units required and units available. A dwelling unit houses a household; a building may contain several units.", "The report puts the deficit at about 1.8 million units in 2021, down from about 2.8 million in 2010. It distinguishes this estimate from the roughly 10.0 million existing dwelling units and the 11.81 million requirement. This figure alone does not settle affordability or housing quality.", "pp. 34–35"),
    item("Access to electricity", "The share of households with access to electricity. It describes household service access, not uninterrupted supply or the share of national energy generated.", "Access rose from 43.8% in 2000 to 86.3% in 2021. Roughly one household in seven still lacked access.", "Figure 4.9, p. 35"),
    item("Improved drinking water", "The share of households using a source classified as improved. The source classification alone does not establish continuous availability or water quality at the point of use.", "Use rose from 60.7% in 2000 to 92.0% in 2021, indicating a substantial expansion of basic services.", "Figure 4.9, p. 35; glossary"),
    item("Improved household toilets", "The share of households using improved toilet facilities. The indicator concerns sanitation facilities and differs from drinking-water access.", "Use rose from 44.8% in 2010 to 69.0% in 2022. Almost one household in three remained outside this category.", "Figure 4.9, p. 35"),
  ],
  protection: [
    item("Gender-based violence", "The reported prevalence of sexual and psychological violence. Each form is a separate measure; the shares overlap and should not be added.", "The report compares 2016 and 2022: sexual violence fell from 10.6% to 6.1% and psychological violence from 48.0% to 25.5%. Psychological violence remained the most prevalent. (The draft edition also showed physical violence; the final edition does not.) The comparison alone does not isolate causes.", "Figure 4.10, p. 36"),
    item("Child marriage", "Marriage involving a person below age 18. The displayed census comparison for females is distinct from the SDG measure of women aged 20–24 who married before 18.", "Figure 4.6 reports 5.2% in 2010 and 2.1% in 2021. The decline indicates progress, while the report stresses that the practice has not ended.", "pp. 32–34; glossary"),
  ],
  gdp: [
    item("Nominal GDP", "The value of goods and services produced at current prices. Increases reflect price changes as well as changes in production.", "GDP rose from GH¢124.5 billion in 2013 to about GH¢1,434.1 billion in 2025. This does not mean the volume produced or household purchasing power rose elevenfold.", "p. 40"),
    item("Real GDP and growth", "Output valued at 2013 prices, removing the effect of price changes. The growth rate compares the volume of output with the previous year.", "Real GDP reached GH¢209.6 billion in 2025, about 68.4% above 2013. Growth was 6.0% in 2025 against 5.8% in 2024, an increase of 0.2 percentage points.", "pp. 42–43"),
    item("Sectoral share of GDP", "The percentage contribution of agriculture, industry and services to nominal GDP. These shares describe output, not employment shares.", "Services contributed 45.9% in 2025, industry 31.3% and agriculture 22.8%. Services are the largest sector.", "p. 41"),
    item("GDP per capita", "GDP divided by total population: average output per person. It is not a measure of how income is distributed or the amount each person earns.", "Nominal output per person rose from GH¢4,710.1 in 2013 to GH¢42,501.9 in 2025. Inflation means the gain in purchasing power is smaller than this nominal increase.", "pp. 41–42"),
  ],
  trade: [
    item("Merchandise exports and imports", "Exports are goods sold abroad; imports are goods bought from abroad. The chart values them in current Ghana cedis.", "In 2025, exports were GH¢401.5 billion and imports GH¢253.2 billion. Their sum, GH¢654.7 billion, is total merchandise trade, not GDP.", "pp. 73–76"),
    item("Merchandise trade balance", "The value of goods exported minus goods imported. A positive balance is a surplus; a negative balance is a deficit.", "The 2025 current-price surplus was GH¢148.3 billion. The report separately records a real merchandise deficit of GH¢3.4 billion after price adjustment. This differs from national-accounts net exports of goods and services.", "pp. 74–78"),
    item("Commodity and partner shares", "Each share is a percentage of exports or imports, as labelled. Continental partner shares group destinations and origins rather than ranking individual countries.", "Gold bullion accounted for 62.9% of exports in 2025, showing concentrated export earnings. Asia took 50.1% of exports; Africa took 17.5% and supplied 14.1% of imports.", "pp. 76–78"),
  ],
  prices: [
    item("Consumer inflation", "The percentage change in the cost of the CPI basket. Year-on-year inflation compares a month with the same month one year earlier; annual average inflation averages across the year.", "Inflation fell from 54.1% in December 2022 to 5.4% in December 2025. The 2025 annual average was 14.6%. Lower inflation means prices increase more slowly, not that they return to previous levels.", "pp. 54–56"),
    item("Food and non-food inflation", "Separate rates of price change for food and for other household goods and services such as transport, rent, health and utilities.", "Food inflation peaked at 61.0% in January 2023 against 47.9% for non-food. By December 2025 the rates were 4.9% and 5.8%. Food pressures matter particularly to households spending a large share of their budget on food.", "p. 55; Table 2.1"),
    item("Producer price inflation", "Changes in the prices producers receive before goods and services reach consumers. The displayed sector figures are year-on-year rates at year-end, not index levels.", "Overall producer price inflation eased from 26.1% in 2024 to 1.9% in 2025. Negative accommodation and transport rates mean producer prices were below the same period a year earlier; they do not establish a return to 2023 prices.", "pp. 58–59"),
    item("Industrial production growth", "Changes in the volume produced by mines, factories, utilities and related industries. It measures production, unlike PPI which measures prices.", "End-period growth in 2025 was 1.9% overall. Manufacturing expanded 6.1%, while mining contracted 1.2% and water-related activities contracted 2.1% in the detailed chart.", "Figure 5.16, p. 59"),
  ],
  labour: [
    item("Labour-force participation", "The share of the working-age population that is employed or unemployed and participating in the labour market.", "Participation rose from 67.1% in 2022 to 74.5% across Q1–Q3 2025. This includes jobseekers and does not mean all participants have work.", "p. 60"),
    item("Employment-to-population ratio", "The share of the working-age population that is employed. It shows how much of that population is actually in work.", "The ratio rose from 58.3% in 2022 to 65.0% across Q1–Q3 2025, after a decline in 2024.", "p. 60"),
    item("Unemployment rate", "The unemployed as a share of the labour force: those without work who are available for and seeking work. It is not a percentage of everyone in an age group.", "Across Q1–Q3 2025, unemployment averaged 12.8% nationally, 32.4% for ages 15–24 and 21.9% for ages 15–35. Youth rates show greater difficulty finding work among young labour-force participants.", "pp. 60–61"),
    item("Youth NEET", "The share of all young people in the relevant age group who are neither employed nor enrolled in education or training. All three conditions apply simultaneously.", "Q1–Q3 2025 averages were 19.1% for ages 15–24 and 17.9% for ages 15–35. In Q3 alone the rates were 21.5% and 19.5%. Quarterly and multi-quarter averages should not be interchanged.", "pp. 61, 111–112"),
  ],
  agriculture: [
    item("Fish production", "The quantity of fish produced, separating marine catch, inland catch and aquaculture (fish farming). One unit on the chart is 100,000 metric tonnes.", "The report’s total rose from 412,658 tonnes in 2010 to 722,648 in 2025. Marine catch remained largest; aquaculture expanded fastest. The report notes revisions between aggregate aquaculture and species totals.", "pp. 45–46"),
    item("Crop production", "The physical quantity harvested, shown in million metric tonnes for the listed crops. It measures output, not yield per hectare or the monetary value of production.", "Cassava rose from about 16.0 million tonnes in 2013 to 28.5 million in 2024; rice rose from 0.6 to 1.1 million. Growing output alone does not establish household food security.", "p. 47"),
    item("Livestock population", "The number of animals of each type, expressed in millions. These are animal counts, distinct from the tonnage of meat produced.", "Between 1990 and 2024 cattle increased from about 1.1 to 2.4 million, sheep from 2.2 to 6.3 million, and poultry from 10.0 to 90.8 million.", "pp. 47–48"),
    item("Agriculture Orientation Index", "Agriculture’s share of government expenditure divided by agriculture’s share of GDP. Below 1 means the budget share is smaller than the sector’s economic share.", "The index was 0.02 in 2022–2024. Public agriculture spending was about 0.2% of GDP in 2024. The two figures have different denominators and should not be confused.", "pp. 44–45"),
    item("Youth agricultural employment", "The census count of young people working in agriculture, forestry and fishing, using the stated age band. It is a count of workers, not the sector’s output.", "For ages 15–24, the count fell from 865,855 in 2010 to 381,476 in 2021; for ages 15–35, from 2,025,551 to 1,222,885. Female participation fell faster. The report discusses possible explanations without measuring their causal contribution.", "p. 114"),
  ],
  tourism: [
    item("Domestic, inbound and outbound tourism", "Domestic flows are residents travelling within Ghana; inbound flows are visitors from abroad; outbound flows are residents travelling abroad. The figures combine same-day and overnight flows and are not a deduplicated count of unique people.", "Domestic travel made up most of the reported flows in 2023. Inbound spending of GH¢15.42 billion exceeded domestic spending of GH¢6.59 billion despite fewer inbound visitors.", "pp. 62, 63"),
    item("Tourism expenditure and purpose", "Money spent during the reported travel category. The GH¢22.01 billion total combines domestic and inbound expenditure; outbound spending is shown separately.", "Funerals (39.3%) and visiting friends or relatives (35.9%) were the main purposes shown for domestic travel. The purpose mix differs for inbound and outbound travel.", "pp. 62, 63"),
  ],
  expenditure: [
    item("Domestic demand", "Spending on consumption and investment within the economy. Its components overlap with the detailed rows and must not be added a second time.", "Domestic demand grew 8.9% in 2025. Household consumption grew 10.5%, while government consumption was broadly flat at −0.1%.", "Table 5.1, p. 42"),
    item("Consumption", "Household purchases for use, government final consumption, and final consumption by non-profit institutions serving households (NPISH). These are spending categories rather than production sectors.", "Consumption totalled GH¢1,203.7 billion at current prices in 2025. Household consumption was the largest component; NPISH consumption declined 14.8% in real terms.", "Table 5.1, p. 42"),
    item("Investment / gross capital formation", "Spending that adds to productive assets and inventories, rather than goods and services consumed immediately.", "Investment grew 7.2% in real terms in 2025, with a nominal level of GH¢117.6 billion.", "Table 5.1, p. 42; glossary"),
    item("Net exports of goods and services", "Exports minus imports under national-accounts coverage and valuation. Real figures use 2013 prices and differ from the current-price, goods-only merchandise balance.", "In 2025 real exports grew 8.2% but imports grew 19.3%, leaving real net exports at −GH¢7.6 billion. The nominal balance was positive at GH¢112.9 billion.", "pp. 43, 78"),
  ],
  enterprises: [
    item("Businesses and establishments", "The census distinguishes businesses inside fixed structures, businesses at open-space spots, and mobile businesses. Establishment statistics refer to the fixed-structure category unless stated otherwise.", "IBES I counted 2,644,358 businesses in 2024: 1,867,690 establishments, 693,748 open-space and 82,920 mobile businesses. Mobile businesses were counted in a single day and may be understated.", "pp. 49–53"),
    item("Establishment size and persons engaged", "Size is based on persons engaged, including owners and unpaid workers. Micro means 1–5, small 6–30, medium 31–100, and large over 100 people.", "Micro establishments were 90.4% of establishments but engaged 41.9% of people. Large firms were just 0.3% of establishments but engaged 21.7%. Around 36% of persons engaged received no pay.", "pp. 50–51"),
    item("Formality and digital finance", "Formality concerns recognised registration and business arrangements; digital finance concerns using tools such as mobile money and electronic payments. Neither is the same as establishment size.", "Only 7.7% of establishments were formal, while 37.2% used digital finance. Formality rose sharply with size, from 5.5% of micro to 64.5% of large establishments.", "pp. 51–52"),
  ],
  fiscal: [
    item("Revenue, grants and tax revenue", "Revenue is government income; grants are transfers received without repayment. Tax revenue is one part of total revenue and grants, not an additional amount to add to it.", "Revenue and grants reached GH¢224.9 billion in 2025, or 15.7% of GDP. Taxes supplied about 82 of every 100 cedis received.", "pp. 64–67"),
    item("Cash and commitment expenditure", "Cash spending counts payments made, including old bills. Commitment spending counts obligations incurred during the year, whether or not paid.", "In 2025 cash spending rose to GH¢268.3 billion while commitment spending fell to GH¢238.7 billion. Clearing earlier arrears explains much of the difference.", "pp. 64–68"),
    item("Compensation, interest and capital expenditure", "Compensation pays public workers; interest is the cost of existing borrowing; capital expenditure pays for lasting assets such as roads and buildings.", "Compensation was GH¢79.0 billion and interest GH¢49.9 billion in 2025. Capital spending fell to GH¢20.2 billion, or 1.4% of GDP, showing a trade-off behind the smaller deficit.", "pp. 67–68"),
    item("Overall fiscal balance", "Revenue and grants minus expenditure, on the stated cash or commitment basis. A negative value is a deficit; a positive value is a surplus.", "The commitment deficit narrowed from 6.9% of GDP in 2024 to 1.0% in 2025. The cash deficit was larger at 3.0% in 2025 because payments included earlier obligations.", "pp. 64–68"),
    item("Primary balance", "The fiscal balance excluding interest on past debt. It shows whether revenue covers expenditure before interest, on the stated accounting basis.", "The 2025 primary balance was a 2.5% of GDP surplus on the commitment basis and 0.5% on the cash basis. A primary surplus does not mean the overall budget is also in surplus.", "pp. 64–68"),
  ],
  finance: [
    item("Broad money (M2+) and growth", "Cash held by the public plus bank deposits covered by the broad-money measure. Growth is the percentage change from the previous year, not a share of GDP.", "M2+ reached GH¢384.3 billion in 2025. Growth slowed from 31.9% in 2024 to 16.5% in 2025.", "pp. 70–71"),
    item("Private-sector credit", "Bank lending to businesses and households. Its nominal level, inflation-adjusted growth and share of GDP answer different questions.", "Credit reached GH¢106.2 billion in 2025 and grew 13.1% after inflation. It nevertheless represented 7.4% of GDP, down from 10.4% in 2022.", "pp. 70–72"),
    item("Bank deposits and assets", "Deposits are customers’ money held in banks. Assets are what banks own or are owed, including loans and investments. Deposits and assets should not be added as separate sources of output.", "Deposits reached GH¢325.3 billion and bank assets GH¢446.9 billion in 2025. Larger balance sheets do not by themselves establish better loan quality.", "pp. 70–72"),
    item("International reserves and import cover", "Foreign reserve assets held by the monetary authorities. Months of import cover express how long these assets could cover the measured import bill.", "Gross international reserves rose from US$9.1 billion in 2024 to US$13.8 billion in 2025, with cover rising from 4.1 to 5.7 months.", "pp. 70–72"),
    item("Policy, interbank and lending rates", "The policy rate guides monetary conditions; the interbank rate concerns lending between banks; the average lending rate concerns loans to customers. They are distinct rates.", "At end-2025 the rates were 18.0%, 16.3% and 20.5%, respectively. All fell from 2024 as inflation eased.", "pp. 70–71"),
    item("Treasury-bill rates", "The interest rates on short-term government borrowing for the stated maturity: 91, 182 or 364 days.", "The 91-day rate fell from 27.7% at end-2024 to 11.1% at end-2025. The 182-day and 364-day rates ended 2025 at 12.5% and 12.9%.", "pp. 70–71"),
    item("Capital adequacy and non-performing loans", "Capital adequacy compares banks’ capital buffer with risk-weighted exposures. The NPL ratio is the share of loans not being repaid as required. Higher capital and lower NPLs generally indicate stronger resilience.", "In 2025 capital adequacy rose to 17.5% and NPLs fell to 18.9%. Nearly one in five cedis lent was still non-performing, so improved resilience did not remove credit risk.", "pp. 70–72"),
    item("Returns on assets and equity", "Return on assets compares profit with bank assets; return on equity compares profit with owners’ funds. The table reports before-tax ROA and after-tax ROE.", "In 2025 ROA was 5.7% and ROE 30.8%. Both had been negative in 2022; the different denominators and tax bases mean the two percentages should not be compared as identical measures.", "pp. 70–72"),
  ],
  informalTrade: [
    item("Informal cross-border trade", "Goods crossing the surveyed land borders without customs recording. The first full survey year is October 2024–September 2025, not calendar-year 2025.", "The survey estimated GH¢38.40 billion of informal trade with Togo, Burkina Faso and Côte d’Ivoire: GH¢20.06 billion of exports and GH¢18.34 billion of imports. Daytime observation excludes night trade and some goods.", "pp. 78–83"),
    item("Informal trade balance and share", "The balance is informal exports less informal imports. The 5.6% share compares informal trade with combined formal and informal trade across the same period.", "The full-year informal surplus was GH¢1.72 billion. It narrowed sharply in Q3 2025, while informal trade exceeded formal trade with the three neighbouring countries. Rounded quarterly values can differ slightly from their component arithmetic.", "Table 5.12, p. 80"),
  ],
  governance: [
    item("Women in Parliament and the courts", "Women’s share of seats in each institution. Each court has its own denominator, so the percentages must not be stacked or added.", "Women held 14.9% of parliamentary seats in 2025. Their shares of High Court, Court of Appeal and Supreme Court judges were 48.8%, 39.0% and 25.0% (Figure 6.2 and Table 2.1). The Supreme Court share fell from a peak of 46.2% in 2023.", "pp. 85–86"),
    item("Requests for gifts and gifts given", "Being directly asked for a gift and actually giving a gift are separate reported experiences. They do not share the same meaning or necessarily the same survey denominator.", "Direct requests increased from 38.6% in January–June 2025 to 50.5% in July–December. The reported share giving gifts fell from 26.7% in 2021 to 16.8% in 2025.", "p. 87"),
    item("No say and no influence", "Survey responses about whether people feel included in government decision-making and able to influence government action. They describe perceptions, not an administrative measure of service delivery.", "No say fell from 42.4% in 2024 to 29.7% in 2025; no influence fell from 43.2% to 33.0%. Lower shares mean fewer respondents felt excluded.", "p. 88"),
    item("Knowledge of the right to vote", "The share of adults aged 18+ who know that voting is a right. Knowing the right and exercising it are different measures.", "The 2024 figure was 98.1%. It should not be described as voter turnout.", "pp. 88–89"),
  ],
  environment: [
    item("Forest reserve area", "The area designated as forest reserve, in square kilometres. This differs from current tree cover or the percentage of each region’s land that is forested.", "The reported December 2025 total was 24,133.53 km². Western, Ashanti and Northern held about 60.8% of the reported area. Four regions are not separately reported in the figure; missing values do not mean no reserves.", "p. 92"),
    item("Carbon retention and stock change", "Carbon retained in soils and vegetation, expressed in million tonnes of carbon (Mt C). This is a stored stock, distinct from the rate of removing carbon from the atmosphere.", "Grassland holds 344.0 Mt C from the chart’s components, while total stock fell from 1,367.5 Mt C in 2015 to 1,147.6 Mt C in 2021. The grassland prose total in the document contains an arithmetic inconsistency.", "p. 93"),
    item("Monthly rainfall", "Rain received during a month, measured in millimetres. Seasonal patterns guide planting and water management; the national pattern does not describe every location equally.", "Rainfall peaked at 216.7 mm in June 2025 and again at 185.1 mm in October. Much of southern Ghana has two rainy seasons, while the north generally has one.", "p. 94"),
    item("Monthly temperature", "Average temperature during each month, expressed in degrees Celsius. It describes seasonal conditions, not a count of heatwave days.", "The 2025 series peaked at 30.4°C in March, cooled to 25.4°C in August and rose to 28.5°C in December. One year’s seasonal curve alone cannot establish a long-term climate trend.", "p. 95"),
  ],
  sdg: [
    item("Multidimensional poverty", "Poverty assessed through several deprivations in living conditions and opportunities, rather than income alone. Incidence is the share classified as poor by this measure.", "Incidence fell from 31.2% in 2022 to 23.0% across Q1–Q3 2025, an 8.2 percentage-point reduction. Nearly one person in four remained poor by this measure.", "p. 97; glossary"),
    item("Food insecurity (FIES)", "Difficulty obtaining adequate food, measured through the Food Insecurity Experience Scale. It differs from crop output, undernourishment and household income.", "Prevalence fell from 44.6% in 2022 to 37.7% in 2024, then rose to 39.8% across Q1–Q3 2025, affecting about 13.0 million people.", "pp. 97–102"),
    item("Maternal mortality ratio", "Maternal deaths per 100,000 live births. This ratio concerns deaths related to pregnancy and childbirth, not all deaths among women.", "The census figures fell from 485 in 2010 to 301 in 2021. The additional 2007 and 2017 figures come from maternal mortality surveys; source methods differ.", "p. 102"),
    item("Under-five, infant and neonatal mortality", "Deaths before age five, before the first birthday, and during the first 28 days of life, respectively, per 1,000 live births. These are related measures with overlapping age ranges and must not be added.", "Under-five mortality fell from 80 in 2008 to 40 in 2022. Neonatal mortality fell from 43 in 2003 to 17 in 2022, while infant mortality was 28 in 2022.", "pp. 102–103"),
    item("Slums and informal settlements", "The household and population shares use different denominators. The map identifies settlements with housing and service limitations; it does not classify whole regions as slums.", "The report gives 29.5% of households (1,404,266) living in slums and 30.8% of the referenced urban population. These should not be treated as interchangeable percentages.", "pp. 103–104"),
    item("Plastic debris density", "The concentration of plastic items along the coast, expressed as million items per square kilometre. It is a density, not total tonnage of plastic waste.", "Density rose from 33.58 in 2016 to 179.76 in 2019, then eased to 152.13 in 2020. It remained more than four times the 2016 level, indicating continuing pressure on coastal environments.", "p. 104"),
  ],
  youth: [
    item("Youth bulge and demographic dividend", "The publication compares youth aged 15–24 and 15–35. A large young population can support economic gains when education, skills and productive jobs expand alongside it; the gain is not automatic.", "The child share fell from 41.8% in 2000 to 35.0% in 2025. About 35% of the population (roughly 12 million people) was aged 15–35 in 2025, close to its 2010 and 2021 levels, and about 20% (6.6 million) was aged 15–24. There are now roughly as many young people as children. These age bands overlap and must not be added.", "pp. 108–110"),
    item("Quarterly youth unemployment", "Unemployed young people as a share of the labour force in the same age band and quarter. It excludes young people outside the labour force from the denominator.", "For ages 15–24 the rate rose from 30.5% in Q2 2025 to 34.4% in Q3. Greater Accra recorded 49.3% in Q3, followed by Central at 48.9%. The rates do not describe all young people as jobseekers.", "p. 111"),
    item("Skills and education alignment", "Reported fit between employed young people’s skills or education and the work they do. The displayed percentages are separate questions and do not form a complete distribution summing to 100%.", "About 65% reported that their skills matched their work, 8% were overqualified and 15% underqualified; 58% reported education–job alignment. The report points to closer links between training and employer demand.", "p. 113"),
    item("Informal employment", "Employment without the formal arrangements and protections associated with more secure work. It differs from establishment registration and from being unemployed.", "The report says more than 70% of employment is informal. Informal work absorbs labour but can involve insecure contracts, irregular earnings and limited protection; this share is for all employment, not a youth-only prevalence estimate.", "pp. 112–113"),
  ],
};

export const indicatorExplanations: Record<string, IndicatorExplanation[]> = Object.fromEntries(
  Object.entries(definitions).map(([group, entries]) => [group, entries.map((entry, index) => ({
    ...entry, why: indicatorSignificance[group]?.[index] ?? "",
  }))]),
);
